css:
/* Buzznerd design layer — site-wide. Everything reads the design-system tokens;
   the only literal is --volt, the brand's yellow "charge" highlight, which has no
   slot in the token set. */
:root {
  --volt: #FFD23F;
  --ink-soft: color-mix(in srgb, var(--ink) 74%, var(--paper));
  --line-soft: color-mix(in srgb, var(--ink) 8%, transparent);
  --accent-tint: color-mix(in srgb, var(--accent) 10%, var(--card));
  --shadow-card: 0 1px 0 color-mix(in srgb, var(--ink) 3%, transparent);
  --shadow-lift: 0 24px 60px -24px color-mix(in srgb, var(--ink) 35%, transparent);
  --shadow-accent: 0 10px 26px color-mix(in srgb, var(--accent) 34%, transparent);
}
html { scroll-behavior: smooth; scroll-padding-top: 90px; }
body { -webkit-font-smoothing: antialiased; }
::selection { background: var(--volt); color: var(--ink); }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; border-radius: 4px; }

/* ---------------------------------------------------------------- type */
.bz-block h1 { font-size: clamp(40px, 4.8vw, var(--text-h1)); line-height: 1.02; letter-spacing: -0.025em; }
.bz-block h2 { font-size: clamp(30px, 3.6vw, var(--text-h2)); line-height: var(--leading-heading); letter-spacing: -0.02em; }
.bz-block h3 { font-weight: 700; letter-spacing: -0.01em; }
.bz-text p { color: var(--ink-soft); font-weight: 500; }
.bz-text strong { color: var(--ink); }
.bz-text a { color: var(--accent); font-weight: 700; }
.bz-text a:hover { text-decoration: underline; }
.bz-headingblock:empty, .bz-text p:has(> a:only-child:empty) { display: none; }
.bz-block--text:has(.bz-text:empty) { display: none; }

/* The eyebrow: the design's "⚡ Label" kicker above every section heading. */
.bz-headingblock .bz-eyebrow { display: inline-flex; align-items: center; gap: 8px; font: 700 13.5px/1.4 var(--font-body); letter-spacing: 0.06em; color: var(--accent); margin-bottom: var(--space-3); }
.bz-headingblock .bz-eyebrow::before { content: '⚡'; letter-spacing: 0; }
/* On an h1 the eyebrow is the pill badge with the yellow bolt tile. */
.bz-headingblock:has(> h1) .bz-eyebrow { background: var(--card); border: 1px solid var(--line-soft); padding: 7px 14px 7px 9px; border-radius: var(--radius-chip); font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--ink); box-shadow: 0 2px 10px color-mix(in srgb, var(--ink) 5%, transparent); }
.bz-headingblock:has(> h1) .bz-eyebrow::before { display: inline-grid; place-items: center; width: 22px; height: 22px; background: var(--volt); border-radius: 6px; font-size: 13px; animation: bz-bolt 1.8s ease-in-out infinite; }
.bz-headingblock:has(> h1) .bz-eyebrow + h1 { margin-top: var(--space-5); }
.bz-center .bz-eyebrow { justify-content: center; }
@keyframes bz-bolt { 0%, 100% { opacity: 1 } 50% { opacity: .45 } }
@keyframes bz-float { 0%, 100% { transform: translateY(0) } 50% { transform: translateY(-14px) } }

/* Ledes: the paragraph straight after a section or hero heading. */
.bz-block--heading + .bz-block--text .bz-text p { font-size: 18px; line-height: 1.55; }
.bz-block--heading + .bz-block--text .bz-center { margin-inline: auto; max-width: 760px; }
.bz-text.bz-center { margin-inline: auto; }

/* ------------------------------------------------------------- buttons */
.bz-btns { gap: 14px; }
.bz-btn { border-radius: var(--radius-chip); font: 700 16px/1 var(--font-body); padding: 16px 28px; transition: transform .18s ease, box-shadow .18s ease, background-color .18s ease; }
.bz-btn:hover { transform: translateY(-2px); }
.bz-btn--primary { background: var(--accent); color: #fff; box-shadow: var(--shadow-accent); }
.bz-btn--primary:hover { background: var(--accent-dark); }
.bz-btn--secondary { background: var(--card); color: var(--ink); border: 1px solid color-mix(in srgb, var(--ink) 14%, transparent); }
.bz-btn--link { color: var(--accent); text-decoration: none; padding: 16px 4px; box-shadow: none; }
.bz-btn--link:hover { text-decoration: underline; transform: none; }
/* On the dark panels the primary action is the volt yellow. */
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-btn--primary { background: var(--volt); color: var(--ink); box-shadow: 0 12px 30px color-mix(in srgb, var(--volt) 30%, transparent); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-btn--secondary { background: rgb(255 255 255 / .1); color: #fff; border-color: rgb(255 255 255 / .18); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-btn--link { color: var(--volt); }
.bz-block--buttons .bz-btns { margin-block: var(--space-3) 0; }
.bz-block--buttons .bz-center .bz-btns { justify-content: center; }

/* A stacked row still lays out twelve tracks, so eleven column gaps survive the
   stack — with a large gap that alone is wider than a phone. Collapse them. */
@media (max-width: 640px) { .bz-row--stack-mobile, .bz-row--stack-tablet { column-gap: 0; row-gap: min(var(--bz-gap, 32px), 32px); } }
@media (min-width: 641px) and (max-width: 1100px) { .bz-row--stack-tablet { column-gap: 0; row-gap: min(var(--bz-gap, 32px), 40px); } }

/* --------------------------------------------------------------- cards */
/* A column's padding is a custom property, so a nested column would inherit
   its card's padding. Reset it; a nested column that sets its own still wins
   (its value is inline). */
.bz-col .bz-col { --bz-col-pad: 0px; }
.bz-col--bg-card { border: 1px solid var(--line-soft); border-radius: var(--radius-card); box-shadow: var(--shadow-card); transition: transform .22s cubic-bezier(.2,.7,.2,1), box-shadow .22s ease; }
.bz-col--bg-card .bz-block { padding-block: var(--space-2); }
.bz-col--bg-card .bz-block h3 { margin: var(--space-2) 0 0; }
.bz-col--bg-card .bz-text p { font-size: 15.5px; line-height: 1.55; color: var(--muted); }
.bz-col--bg-paper { border-radius: var(--radius-card); }
/* Dark panels: the spotlight cards, CTA band and dark feature tiles. */
.bz-col--bg-ink { border-radius: var(--radius-modal); position: relative; overflow: hidden; background: radial-gradient(circle at 92% 0%, color-mix(in srgb, var(--accent) 30%, transparent), transparent 42%), radial-gradient(circle at 0% 100%, color-mix(in srgb, var(--volt) 14%, transparent), transparent 40%), var(--ink); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-text p { color: color-mix(in srgb, #fff 72%, var(--ink)); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-text strong { color: #fff; }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-eyebrow { color: var(--volt); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) :is(h1, h2, h3) { color: #fff; }

/* Feature lists: ⚡ tiles beside items that carry a description, ✓ ticks on a
   plain checklist. */
.bz-block--list .bz-grid { gap: var(--space-4) var(--space-5); }
.bz-feature { position: relative; padding-left: 44px; }
.bz-feature::before { content: '⚡'; position: absolute; left: 0; top: 0; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 9px; background: var(--accent-tint); font-size: 15px; }
.bz-feature:not(:has(.bz-feature__d)) { padding-left: 34px; }
.bz-feature:not(:has(.bz-feature__d))::before { content: '✓'; width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: #fff; font: 800 12px/1 var(--font-body); top: 1px; }
.bz-block .bz-feature__t { font: 700 16px/1.35 var(--font-body); color: var(--ink); margin: 0 0 4px; letter-spacing: 0; }
.bz-block .bz-feature__d { font-size: 14.5px; font-weight: 500; margin: 0; }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-feature__t { color: #fff; }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-feature__d { color: color-mix(in srgb, #fff 65%, var(--ink)); }
:is(.bz-section--bg-ink, .bz-col--bg-ink) .bz-feature::before { background: rgb(255 255 255 / .1); }

/* Stats (statBand used as a plain stat row inside a column). */
.bz-col .bz-block--statBand { background: none; color: inherit; padding-block: var(--space-3); }
.bz-col .bz-block--statBand .bz-band { grid-template-columns: 1fr; }
.bz-col .bz-block--statBand .bz-stats { display: flex; flex-wrap: wrap; gap: var(--space-4); }
.bz-col .bz-block--statBand .bz-stat { flex: 1 1 140px; border: 1px solid var(--line-soft); background: var(--card); border-radius: 16px; padding: 18px 20px; }
.bz-col .bz-block--statBand .bz-stat__v { font: 800 32px/1 var(--font-heading); color: var(--accent); letter-spacing: -0.02em; }
.bz-col .bz-block--statBand .bz-stat__l { color: var(--muted); font-weight: 600; font-size: 14px; margin-top: 6px; }

/* Images */
.bz-block .bz-logo__img { height: var(--bz-logo-h, 34px); width: auto; max-width: none; }
.bz-figure img { border-radius: var(--radius-card); }

/* ---------------------------------------------------------- testimonials */
.bz-block--testimonials .bz-grid { gap: 20px; }
.bz-quote { border-radius: var(--radius-card); border-color: var(--line-soft); padding: 28px; box-shadow: var(--shadow-card); display: flex; flex-direction: column; }
.bz-stars { color: var(--warn); letter-spacing: 3px; font-size: 15px; }
.bz-quote blockquote { font-size: 15.5px; line-height: 1.6; color: var(--ink-soft); font-weight: 500; flex: 1; margin-bottom: var(--space-5); }
.bz-quote__n { font: 700 15px/1.3 var(--font-body); }
.bz-quote__r { font-size: 13.5px; font-weight: 500; }

/* ------------------------------------------------------------------ FAQ */
.bz-faqs { gap: 12px; max-width: 900px; margin-inline: auto; }
.bz-faq { border-radius: 16px; border-color: var(--line-soft); padding: 0; transition: border-color .2s ease; }
.bz-faq[open] { border-color: color-mix(in srgb, var(--accent) 35%, transparent); }
.bz-faq summary { list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 20px 24px; font: 700 17px/1.4 var(--font-body); color: var(--ink); }
.bz-faq summary::-webkit-details-marker { display: none; }
.bz-faq summary::after { content: '+'; flex: none; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; background: var(--accent-tint); color: var(--accent); font: 700 20px/1 var(--font-body); }
.bz-faq[open] summary::after { content: '\2212'; }
.bz-faq__a { padding: 0 24px 22px; margin: 0; font-size: 15.5px; line-height: 1.6; font-weight: 500; color: var(--muted); }

/* ---------------------------------------------------------------- forms */
.bz-form { max-width: none; border: 0; padding: 0; background: none; gap: 14px; }
.bz-form__t { display: none; }
.bz-label { font: 600 13.5px/1.2 var(--font-body); color: var(--ink-soft); }
.bz-input { border-radius: var(--radius-input); border: 1.5px solid color-mix(in srgb, var(--ink) 12%, transparent); background: var(--paper); padding: 15px 16px; font: 500 15.5px/1.4 var(--font-body); }
.bz-input:focus { outline: none; border-color: var(--accent); background: var(--card); }
.bz-form .bz-btn { width: 100%; padding: 17px 28px; font-size: 16.5px; }
.bz-form__status[data-state='ok'] { background: var(--paper); border: 1.5px solid color-mix(in srgb, var(--accent) 30%, transparent); border-radius: var(--radius-card); padding: 40px 32px; text-align: center; color: var(--ink); font: 700 20px/1.4 var(--font-heading); }
.bz-form__status[data-state='ok']::before { content: '⚡'; display: block; font-size: 38px; margin-bottom: 8px; }

/* ---------------------------------------------------------------- posts */
.bz-post { border-radius: var(--radius-card); border-color: var(--line-soft); }

@media (max-width: 640px) {
  .bz-btn { padding: 15px 22px; }
  .bz-col--bg-ink, .bz-col--bg-card { padding: var(--space-5); }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before { animation: none !important; transition: none !important; }
}

/* ------------------------------------------------------- CTA band pattern
   The closing band on most pages: a section "cta" holding one ink column
   "cta-card" with a bolt, a centred heading, a line of copy and buttons. Built
   from ordinary blocks so each page keeps its own Buttons-library actions. */
[data-bz-node="cta-card"] { text-align: center; }
[data-bz-node="cta-card"] .bz-block { padding-block: 0; }
[data-bz-node="cta-bolt"] p { font-size: 40px; line-height: 1; animation: bz-bolt 1.8s ease-in-out infinite; }
[data-bz-node="cta-h"] h2 { font-size: clamp(34px, 4.6vw, 62px); line-height: 1.02; letter-spacing: -.025em; max-width: 760px; margin: 12px auto 0; }
[data-bz-node="cta-body"] p { font-size: 18.5px; line-height: 1.55; max-width: 560px; margin: 18px auto 0 !important; }
[data-bz-node="cta-btns"] .bz-btns { margin-top: 34px; }
[data-bz-node="cta-btns"] .bz-btn { font-size: 17px; padding: 17px 32px; }
[data-bz-node="cta-extra"] p { margin-top: 18px !important; }

/* ------------------------------------------------------------ hero pattern
   Every page opens with a section "hero": the two soft glows behind it and a
   gently floating illustration in "hero-img". */
[data-bz-node="hero"] { overflow: clip; }
[data-bz-node="hero"]::before, [data-bz-node="hero"]::after { content: ''; position: absolute; border-radius: 50%; filter: blur(8px); pointer-events: none; }
[data-bz-node="hero"]::before { top: -40px; right: 6%; width: 340px; height: 340px; background: radial-gradient(circle, color-mix(in srgb, var(--accent) 18%, transparent), transparent 68%); }
[data-bz-node="hero"]::after { top: 220px; left: -60px; width: 300px; height: 300px; background: radial-gradient(circle, color-mix(in srgb, var(--volt) 22%, transparent), transparent 68%); }
[data-bz-node="hero"] > .bz-container { position: relative; z-index: 1; }
[data-bz-node="hero-img"] img { animation: bz-float 6s ease-in-out infinite; border-radius: 0; }
[data-bz-node="hero-trust"] p { font-size: 14.5px !important; font-weight: 600 !important; }
[data-bz-node="hero-chip"] { margin-top: -40px; position: relative; }

/* ------------------------------------------------------------------ blog
   Post pages are <main><article>; the generated blog index is the only page
   whose body is a bare <section class="bz-block">. */
main > article { padding-block: var(--space-6) var(--space-7); }
main > article .bz-container { max-width: 760px; margin-inline: auto; }
main > article > .bz-block:first-child .bz-container:last-child { max-width: 940px; margin-top: var(--space-5); }
main > article > .bz-block:first-child img { width: 100%; height: auto; max-height: 460px; object-fit: cover; border-radius: 22px; border: 1px solid var(--line-soft); box-shadow: 0 30px 70px -34px color-mix(in srgb, var(--ink) 40%, transparent); }
main > article h1 { font-size: clamp(30px, 4vw, 52px); line-height: 1.05; }
main > article .bz-eyebrow { color: var(--muted); font: 600 13.5px/1.4 var(--font-body); letter-spacing: 0; text-transform: none; }
main > article [data-bz-node="post-meta"] p { font-size: 13.5px; font-weight: 600; color: var(--muted); }
main > article [data-bz-node="post-meta"] strong { display: inline-block; background: var(--accent-tint); color: var(--accent); font-size: 12px; letter-spacing: .05em; text-transform: uppercase; padding: 6px 12px; border-radius: var(--radius-chip); margin-right: 4px; }
main > article [data-bz-node="post-dek"] p { font-size: 19.5px; line-height: 1.5; color: var(--ink-soft); }
main > article .bz-text p { font-size: 17.5px; line-height: 1.72; font-weight: 400; color: var(--ink-soft); }
main > article .bz-text a { text-decoration: underline; text-underline-offset: 2px; }
main > article h2 { font-size: clamp(26px, 3vw, 34px); margin-top: var(--space-5); }
main > article h3 { font-size: 22px; margin-top: var(--space-4); }
main > article .bz-col--bg-paper { border-left: 4px solid var(--accent); border-radius: 0 14px 14px 0; background: color-mix(in srgb, var(--accent) 6%, var(--card)); }
main > article .bz-col--bg-paper p { font-size: 18px !important; color: var(--ink) !important; }
main > article .bz-row { max-width: 760px; margin-inline: auto; padding-inline: var(--container-pad, 16px); }

main > section.bz-block { padding-block: var(--space-7); }
main > section.bz-block h1 { font-size: clamp(36px, 4.4vw, 60px); line-height: 1.04; letter-spacing: -.025em; max-width: 900px; }
main > section.bz-block .bz-lede { font-size: 18.5px; font-weight: 500; color: var(--ink-soft); max-width: 680px; margin-bottom: var(--space-6); }
main > section.bz-block .bz-bare { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 22px; }
main > section.bz-block .bz-loc { display: flex; flex-direction: column; gap: 10px; background: var(--card); border: 1px solid var(--line-soft); border-radius: var(--radius-card); padding: 26px; transition: transform .22s cubic-bezier(.2,.7,.2,1), box-shadow .22s ease; }
main > section.bz-block .bz-loc:hover { transform: translateY(-6px); box-shadow: var(--shadow-lift); }
main > section.bz-block .bz-loc strong { font: 700 19px/1.3 var(--font-heading); color: var(--ink); }
main > section.bz-block .bz-loc a:hover strong { color: var(--accent); }
main > section.bz-block .bz-loc__s { font-size: 14.5px; line-height: 1.55; color: var(--muted); font-weight: 500; }

/* ---------------------------------------------------------------- chrome
   Header (default template) and footer (Site footer component). Kept here, in
   the site design layer, because this is the one stylesheet that reaches every
   surface: brand pages, the generated blog index, and the /store storefront's
   /partials/chrome.css. */
/* Header: the sticky frosted bar. No ancestor may clip overflow — the dropdowns hang below it. */
[data-bz-node="header"] { position: sticky; top: 0; z-index: 50; background: color-mix(in srgb, var(--paper) 82%, transparent); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border-bottom: 1px solid var(--line-soft); }
[data-bz-node="header-row"] { align-items: center; }
[data-bz-node="header-row"] .bz-block { padding-block: 0; }
[data-bz-node="header-nav"] .bz-nav { gap: 30px; }
[data-bz-node="header-nav"] .bz-navitem > a { font: 600 15px/1.2 var(--font-body); color: var(--ink); position: relative; padding-block: 6px; }
[data-bz-node="header-nav"] .bz-nav > .bz-navitem > a::after { content: ''; position: absolute; left: 0; bottom: 0; height: 2px; width: 0; background: var(--accent); transition: width .25s ease; }
[data-bz-node="header-nav"] .bz-nav > .bz-navitem > a:hover::after,
[data-bz-node="header-nav"] .bz-nav > .bz-navitem > a[aria-current="page"]::after { width: 100%; }
[data-bz-node="header-nav"] .bz-nav > .bz-navitem--has-sub > a::before { content: '▾'; position: absolute; right: -14px; top: 7px; font-size: 10px; color: var(--muted); }
[data-bz-node="header-nav"] .bz-subnav { left: 50%; transform: translateX(-50%); margin-top: 14px; min-width: 300px; padding: 12px; gap: 2px; border-radius: 18px; border-color: color-mix(in srgb, var(--ink) 10%, transparent); box-shadow: var(--shadow-lift); }
[data-bz-node="header-nav"] .bz-subnav::before { content: ''; position: absolute; left: 0; right: 0; top: -16px; height: 16px; }
/* Two-column dropdown for long submenus — desktop bar only, never inside the mobile drawer. */
@media (min-width: 1101px) {
  [data-bz-node="header-nav"] .bz-navitem--has-sub:has(> .bz-subnav > :nth-child(6)) > .bz-subnav { display: none; grid-template-columns: 1fr 1fr; min-width: 560px; }
  [data-bz-node="header-nav"] .bz-navitem--has-sub:has(> .bz-subnav > :nth-child(6)):is(:hover, :focus-within, [data-open]) > .bz-subnav { display: grid; }
}
[data-bz-node="header-nav"] .bz-subnav .bz-navitem > a { display: block; padding: 11px 12px; border-radius: 12px; font: 600 14.5px/1.35 var(--font-body); white-space: nowrap; }
[data-bz-node="header-nav"] .bz-subnav .bz-navitem > a:hover { background: var(--paper); color: var(--accent-dark); }
[data-bz-node="header-cta"] .bz-btns { justify-content: flex-end; align-items: center; margin: 0; flex-wrap: nowrap; gap: 18px; }
[data-bz-node="header-cta"] .bz-btn { padding: 11px 20px; font-size: 15px; white-space: nowrap; }
[data-bz-node="header-cta"] .bz-btn--link { color: var(--ink); font-weight: 600; padding-inline: 0; }
@media (max-width: 1100px) {
  [data-bz-node="header-row"] { grid-template-columns: auto 1fr; }
  [data-bz-node="header-brand"] { grid-column: 1; grid-row: 1; }
  [data-bz-node="header-nav"] { grid-column: 2; grid-row: 1; justify-self: end; }
  [data-bz-node="header-cta"] { display: none; }
  [data-bz-node="header-nav"] .bz-menu-wrap { justify-content: flex-end; }
  [data-bz-node="header-nav"] .bz-menu-wrap[data-open] > .bz-menu { background: var(--card); box-shadow: var(--shadow-lift); max-height: calc(100vh - 80px); overflow-y: auto; }
  [data-bz-node="header-nav"] .bz-subnav { position: static; display: flex; transform: none; min-width: 0; box-shadow: none; border: 0; padding: 4px 0 0 12px; margin: 0; }
  [data-bz-node="header-nav"] .bz-nav > .bz-navitem--has-sub > a::before { display: none; }
  [data-bz-node="header-nav"] .bz-subnav .bz-navitem > a { white-space: normal; }
}
[data-bz-node="footer-band"] { background: var(--card); border-top: 1px solid var(--line-soft); }
[data-bz-node="footer-band"] .bz-block { padding-block: 0; }
[data-bz-node="footer-tagline"] p { font-size: 14.5px; line-height: 1.6; color: var(--muted); max-width: 280px; margin-top: 16px; }
[data-bz-node="footer-place"] p { font-size: 13.5px; font-weight: 600; color: var(--muted); margin-top: 12px; }
[data-bz-node="footer-social"] { margin-top: 18px; }
[data-bz-node="footer-social"] .bz-nav { gap: 10px; }
[data-bz-node="footer-social"] .bz-navitem > a { display: grid; place-items: center; height: 40px; padding: 0 14px; border-radius: 11px; background: var(--paper); border: 1px solid var(--line-soft); font: 600 13px/1 var(--font-body); }
[data-section-footer-heading], [data-bz-section="site-footer"] .bz-block--heading h3 { font: 700 13px/1.2 var(--font-body); letter-spacing: .08em; text-transform: uppercase; color: var(--ink); margin: 0 0 16px; }
[data-bz-section="site-footer"] .bz-menu--vertical .bz-nav { gap: 11px; }
[data-bz-section="site-footer"] .bz-menu--vertical .bz-navitem > a { font: 500 14.5px/1.3 var(--font-body); color: var(--muted); padding: 0; }
[data-bz-section="site-footer"] .bz-menu--vertical .bz-navitem > a:hover { color: var(--accent); }
[data-bz-node="footer-start"] .bz-btns { margin: 0; }
