/* Blog listing (/blog) — the design handoff's index.
   The platform generates this page as a plain list of post titles and
   descriptions, and loads no template script on it, so this lives here — but it
   returns at once on any page that is not that generated list. It turns the
   list into the handoff's featured card + card grid, reads each post's cover,
   category, date and read time from the post's own page (cached for the
   session), and builds the category chips on the platform's `filter`
   behaviour. Without it the page is still a complete list of every post. */
(function () {
  var section = document.querySelector('main > section.bz-block');
  var list = section && section.querySelector(':scope > .bz-container > ul.bz-bare');
  if (!list || document.querySelector('main > article') || !list.querySelector(':scope > li.bz-loc')) return;

  var container = list.parentNode;
  var h1 = container.querySelector(':scope > h1');
  var lede = container.querySelector(':scope > .bz-lede');
  var GLYPH = { 'artificial-intelligence': '⚡', product: '🔌', 'case-study': '📈', insights: '💡', company: '🎸', events: '📣', industry: '🚛' };
  var CACHE = 'bnb-blog-cards-v1';

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }
  function key(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
  function readCache() { try { return JSON.parse(sessionStorage.getItem(CACHE) || '{}') || {}; } catch (e) { return {}; } }
  function writeCache(data) { try { sessionStorage.setItem(CACHE, JSON.stringify(data)); } catch (e) { /* private mode */ } }

  section.classList.add('bnb-index');
  list.classList.add('bnb-grid');

  /* Hero */
  var eyebrow = el('p', 'bnb-eyebrow');
  var bolt = el('span', 'bnb-eyebrow__icon', '⚡');
  bolt.setAttribute('aria-hidden', 'true');
  eyebrow.appendChild(bolt);
  eyebrow.appendChild(document.createTextNode('The Buzznerd Blog'));
  if (h1) {
    container.insertBefore(eyebrow, h1);
    var phrase = 'commercial truck';
    var walker = document.createTreeWalker(h1, NodeFilter.SHOW_TEXT);
    for (var t = walker.nextNode(); t; t = walker.nextNode()) {
      var at = t.nodeValue.indexOf(phrase);
      if (at < 0) continue;
      var rest = t.splitText(at);
      rest.splitText(phrase.length);
      var em = el('em', null, phrase);
      rest.parentNode.replaceChild(em, rest);
      break;
    }
  }

  /* Posts, newest first, as the build listed them. */
  var posts = Array.prototype.map.call(list.querySelectorAll(':scope > li.bz-loc'), function (li) {
    var a = li.querySelector('a');
    var desc = li.querySelector('.bz-loc__s');
    return { li: li, href: a ? a.getAttribute('href') : '#', title: a ? a.textContent.trim() : '', desc: desc ? desc.textContent.trim() : '', views: [] };
  });
  if (!posts.length) return;

  function card(post, featured) {
    var a = el('a', featured ? 'bnb-featured bnb-card' : 'bnb-post bnb-card');
    a.href = post.href;
    var media = el('div', 'bnb-media');
    var glyph = el('span', 'bnb-media__glyph', '⚡');
    glyph.setAttribute('aria-hidden', 'true');
    media.appendChild(glyph);
    var body = el('div', featured ? 'bnb-featured__body' : 'bnb-post__body');
    var row = el('div', 'bnb-row');
    var tag = el('span', 'bnb-tag');
    tag.hidden = true;
    var meta = el('span', 'bnb-meta');
    row.appendChild(tag);
    row.appendChild(meta);
    body.appendChild(row);
    body.appendChild(el(featured ? 'h2' : 'h3', null, post.title));
    if (post.desc) body.appendChild(el('p', null, post.desc));
    var more = el('span', 'bnb-readmore');
    more.appendChild(el('span', 'bnb-link', featured ? 'Read the article →' : 'Read more →'));
    body.appendChild(more);
    a.appendChild(media);
    a.appendChild(body);
    post.views.push({ media: media, glyph: glyph, tag: tag, meta: meta, eager: featured });
    return a;
  }

  var featuredWrap = el('div', 'bnb-featured-wrap');
  featuredWrap.appendChild(card(posts[0], true));
  container.insertBefore(featuredWrap, list);

  posts.forEach(function (post, i) {
    var li = post.li;
    li.className = 'bnb-item' + (i === 0 ? ' bnb-item--featured' : '');
    li.setAttribute('data-bz-part', 'item');
    li.textContent = '';
    li.appendChild(card(post, false));
  });

  var empty = el('p', 'bnb-empty', 'No posts in this category yet.');
  empty.setAttribute('data-bz-part', 'empty');
  empty.hidden = true;
  container.insertBefore(empty, list.nextSibling);

  /* Fill one post's cards from its data. */
  function fill(post, data) {
    var cat = key(data.category);
    post.category = data.category || '';
    post.li.setAttribute('data-cat', cat);
    post.views.forEach(function (v) {
      v.media.setAttribute('data-cat', cat);
      v.glyph.textContent = GLYPH[cat] || '⚡';
      if (data.cover && !v.media.querySelector('img')) {
        var img = el('img');
        img.alt = '';
        img.decoding = 'async';
        if (!v.eager) img.loading = 'lazy';
        img.src = data.cover;
        v.media.appendChild(img);
      }
      if (data.category) { v.tag.textContent = data.category; v.tag.hidden = false; }
      v.meta.textContent = [data.date, data.read ? data.read + ' min read' : ''].filter(Boolean).join(' · ');
    });
  }

  function shortDate(text) {
    var d = new Date(text);
    return isNaN(d.getTime()) ? text : d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
  }

  function parse(html) {
    var doc = new DOMParser().parseFromString(html, 'text/html');
    var img = doc.querySelector('main > article > .bz-block:not([data-bz-node]) img');
    var date = doc.querySelector('main > article .bz-prose > .bz-eyebrow');
    var meta = doc.querySelector('main > article [data-bz-node="post-meta"]');
    var cat = meta && meta.querySelector('strong');
    var read = meta && (meta.textContent.match(/(\d+)\s*min read/i) || [])[1];
    return {
      cover: img ? img.getAttribute('src') : '',
      date: date ? shortDate(date.textContent.trim()) : '',
      category: cat ? cat.textContent.trim() : '',
      read: read || '',
    };
  }

  /* Chips, once every post's category is known: "All", then each category in
     the order the newest posts introduce them. The platform filter does the
     rest — aria-pressed, the count and the empty state. */
  function chips() {
    var seen = {};
    var cats = [];
    posts.forEach(function (p) {
      var k = key(p.category);
      if (k && !seen[k]) { seen[k] = true; cats.push({ k: k, name: p.category }); }
    });
    if (cats.length < 2) return;
    var group = el('div', 'bnb-filter');
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', 'Filter posts by category');
    [{ k: 'all', name: 'All' }].concat(cats).forEach(function (c) {
      var b = el('button', 'bnb-chip', c.name);
      b.type = 'button';
      b.setAttribute('data-bz-part', 'control');
      b.setAttribute('data-bz-facet', 'cat');
      b.setAttribute('data-bz-value', c.k);
      b.setAttribute('aria-pressed', c.k === 'all' ? 'true' : 'false');
      group.appendChild(b);
    });
    var status = el('p', 'bz-sr');
    status.setAttribute('data-bz-part', 'count');
    status.setAttribute('data-bz-count-template', '{n} posts shown');
    status.setAttribute('aria-live', 'polite');
    container.insertBefore(group, featuredWrap);
    container.insertBefore(status, featuredWrap);
    section.setAttribute('data-bz-behavior', 'filter');
    if (window.BuzzNerd && window.BuzzNerd.initBehaviours) window.BuzzNerd.initBehaviours(section.parentNode);
  }

  var cache = readCache();
  var queue = [];
  posts.forEach(function (post) {
    if (cache[post.href]) fill(post, cache[post.href]);
    else queue.push(post);
  });
  if (!queue.length) return chips();

  var running = 0;
  var left = queue.length;
  function done() {
    left -= 1;
    if (left === 0) { writeCache(cache); chips(); }
    else next();
  }
  function next() {
    while (running < 6 && queue.length) {
      var post = queue.shift();
      running += 1;
      fetch(post.href, { credentials: 'same-origin' })
        .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
        .then((function (p) { return function (html) { var data = parse(html); cache[p.href] = data; fill(p, data); }; })(post))
        .catch(function () { /* that card keeps its title and excerpt */ })
        .then(function () { running -= 1; done(); });
    }
  }
  next();
})();
